// Regenerate with pier's palette (D154); source revisions: testdata/README.md.
//
//	node --experimental-strip-types coding/interactive/testdata/regenerate.mjs ./pi --write
//
// The golden file is generated by running the upstream theme module with Node
// (coding/interactive/testdata/theme_golden.txt): every color token's ANSI sequence for the
// built-in dark/light themes in both color modes, the style helpers, the
// thinking/bash border colors, and the terminal-theme detection helpers.

func writeThemeFile(t *testing.T, dir string, file string, name string, accent string) {
	t.Helper()
	colors := map[string]any{}
	for _, key := range requiredThemeColors {
		colors[key] = accent
	}
	document := map[string]any{"name": name, "colors": colors}
	data, err := json.Marshal(document)
	if err != nil {
		t.Fatalf("marshal theme: %v", err)
	}
	if err := os.WriteFile(dir+"/"+file, data, 0o644); err != nil {
		t.Fatalf("write theme: %v", err)
	}
}

// TestThemeHandleResolvesTheCurrentTheme pins the Proxy-equivalent handle:
// ActiveTheme returns a stable pointer whose Fg/Bg resolve the current concrete
// theme, so holders recolor on a switch without a rebuild.
func TestThemeHandleResolvesTheCurrentTheme(t *testing.T) {
	SetCustomThemesDir(t.TempDir())
	SetRegisteredThemes(nil)
	InitTheme("dark", false)

	handle := ActiveTheme()
	if got, want := handle.Fg("accent", "x"), mustLoadTheme("dark").Fg("accent", "x"); got != want {
		t.Fatalf("dark handle = %q want %q", got, want)
	}

	SetTheme("light", false)
	if ActiveTheme() != handle {
		t.Fatal("ActiveTheme returned a new pointer; captured holders would go stale")
	}
	if got, want := handle.Fg("accent", "x"), mustLoadTheme("light").Fg("accent", "x"); got != want {
		t.Fatalf("light handle = %q want %q", got, want)
	}
	if handle.ColorMode() != mustLoadTheme("light").ColorMode() {
		t.Fatal("ColorMode did not resolve the new theme")
	}
}

// TestMarkdownThemeRecolorsAfterASwitch pins that a factory built once from the
// handle recolors on invalidate after a theme switch.
func TestMarkdownThemeRecolorsAfterASwitch(t *testing.T) {
	SetCustomThemesDir(t.TempDir())
	SetRegisteredThemes(nil)
	InitTheme("dark", false)

	markdown := tui.NewMarkdown("# heading\n\nbody text", 0, 0, GetMarkdownTheme(), nil, tui.MarkdownOptions{})
	dark := strings.Join(markdown.Render(40), "\n")

	SetTheme("light", false)
	markdown.Invalidate()
	light := strings.Join(markdown.Render(40), "\n")

	if dark == light {
		t.Fatalf("markdown did not recolor:\n%s", dark)
	}
}

// GetThemeForRgbColor must match upstream terminalAppearance with no
// foreground: a medium-gray background is light because black text contrasts
// better, not dark at a 0.5 luminance threshold.
func TestGetThemeForRgbColorMatchesTerminalAppearance(t *testing.T) {
	for _, gray := range []int{100, 150, 180} {
		want := TerminalAppearance(tui.RgbColor{R: gray, G: gray, B: gray}, nil)
		if got := string(GetThemeForRgbColor(RgbColor{R: gray, G: gray, B: gray})); got != want {
			t.Errorf("GetThemeForRgbColor(%d) = %s; want %s", gray, got, want)
		}
	}
}

// Upstream detectColorFgBgTheme reads only the last COLORFGBG segment, requires
// 1-2 digits, and rejects indices above 15.
func TestColorFgBgIndexMatchesUpstream(t *testing.T) {
	if _, ok := getColorFgBgBackgroundIndex("0;300"); ok {
		t.Fatal("a 3-digit background index must be rejected")
	}
	if _, ok := getColorFgBgBackgroundIndex("0;20"); ok {
		t.Fatal("an index above 15 must be rejected")
	}
	if index, ok := getColorFgBgBackgroundIndex("0;8"); !ok || index != 8 {
		t.Fatalf("0;8 = %d, %v; want 8, true", index, ok)
	}
}

// Upstream detectColorFgBgTheme classifies the COLORFGBG index like Vim: 0-6
// and 8 are dark, 7 and 9-15 are light.
func TestColorFgBgThemeClassifiesByIndex(t *testing.T) {
	envWith := func(value string) func(string) string {
		return func(key string) string {
			if key == "COLORFGBG" {
				return value
			}
			return ""
		}
	}
	if got := DetectTerminalBackgroundFromEnv(envWith("0;9")).Theme; got != TerminalThemeLight {
		t.Fatalf("index 9 = %s; want light", got)
	}
	if got := DetectTerminalBackgroundFromEnv(envWith("0;12")).Theme; got != TerminalThemeLight {
		t.Fatalf("index 12 = %s; want light", got)
	}
	if got := DetectTerminalBackgroundFromEnv(envWith("0;8")).Theme; got != TerminalThemeDark {
		t.Fatalf("index 8 = %s; want dark", got)
	}
}

// Dim tokens are blended 40% toward the theme background (upstream theme.ts
// `dimTokens`); a token that is not dim keeps its declared color.
func TestDimTokensAreBlendedTowardTheBackground(t *testing.T) {
	SetCustomThemesDir(t.TempDir())
	SetRegisteredThemes(nil)
	SetTrueColorSupport(true)
	SetStyleColorsEnabled(true)
	InitTheme("dark", false)
	theme := NewTheme(
		map[string]ColorValue{"text": {Value: "#ff0000"}, "muted": {Value: "#00ff00"}},
		nil, ColorModeTruecolor, "probe", "", "muted")
	colors := theme.Colors()
	if colors["muted"] == colors["text"] {
		t.Fatalf("dim token and body token resolved identically: %+v", colors)
	}
	declared := mustParseThemeColor("#00ff00")
	if colors["muted"] == declared {
		t.Fatalf("dim token kept its declared color %v; want a background blend", declared)
	}
	if colors["text"] != mustParseThemeColor("#ff0000") {
		t.Fatalf("body token = %v, want its declared color", colors["text"])
	}
}

// Reference: pi v1.4.0 (4a080252), theme/theme.ts startThemeWatcher excludes
// SYSTEM_THEME_NAME. A file named system.json must never replace the generated
// system theme when it changes.
func TestSystemThemeDoesNotWatchAFileNamedSystem(t *testing.T) {
	synctest.Test(t, func(t *testing.T) {
		StopThemeWatcher()
		SetRegisteredThemes(nil)
		SetCustomThemesDir(t.TempDir())
		OnThemeChange(func() {})
		defer func() {
			StopThemeWatcher()
			SetRegisteredThemes(nil)
			SetCustomThemesDir("")
		}()

		dir := CustomThemesDir()
		file := filepath.Join(dir, "system.json")
		writeThemeFile(t, dir, "system.json", SystemThemeName, "#123456")
		old := time.Now().Add(-time.Minute)
		if err := os.Chtimes(file, old, old); err != nil {
			t.Fatal(err)
		}
		if ok, message := SetTheme(SystemThemeName, true); !ok {
			t.Fatalf("SetTheme(system) failed: %s", message)
		}
		// Let the watcher take its initial mtime snapshot before changing the file.
		time.Sleep(300 * time.Millisecond)
		writeThemeFile(t, dir, "system.json", SystemThemeName, "#abcdef")

		deadline := time.Now().Add(750 * time.Millisecond)
		for time.Now().Before(deadline) {
			if got := CurrentTheme().SourcePath; got != "" {
				t.Fatalf("system theme was replaced by watched file %q", got)
			}
			time.Sleep(10 * time.Millisecond)
		}
	})
}

// Reference: pi v1.5.2 (b4afdddf) modes/interactive/theme/theme.ts isLightTheme
// loads the named theme (or the current one) and reports whether its appearance
// is light. Pier compared the name against "light", so a custom light theme,
// the current theme, and the system theme all read as dark.
func TestIsLightThemeResolvesTheThemeAppearance(t *testing.T) {
	dir := t.TempDir()
	SetCustomThemesDir(dir)
	SetRegisteredThemes(nil)
	t.Cleanup(func() {
		SetCustomThemesDir("")
		SetRegisteredThemes(nil)
		StopThemeWatcher()
	})
	colors := map[string]any{}
	for _, key := range requiredThemeColors {
		colors[key] = "#101010"
	}
	document := map[string]any{"name": "paperlight", "appearance": "light", "colors": colors}
	encoded, err := json.Marshal(document)
	if err != nil {
		t.Fatal(err)
	}
	if err := os.WriteFile(filepath.Join(dir, "paperlight.json"), encoded, 0o644); err != nil {
		t.Fatal(err)
	}

	if !IsLightTheme("light") {
		t.Fatal("the light theme must be light")
	}
	if IsLightTheme("dark") {
		t.Fatal("the dark theme must not be light")
	}
	if !IsLightTheme("paperlight") {
		t.Fatal("a custom theme declaring a light appearance must be light")
	}

	// The empty name resolves the current theme.
	InitTheme("light", false)
	if !IsLightTheme("") {
		t.Fatal("the current light theme must be light when the name is empty")
	}
	InitTheme("dark", false)
	if IsLightTheme("") {
		t.Fatal("the current dark theme must not be light when the name is empty")
	}

	// D552: upstream's isLightTheme calls loadTheme, which throws
	// `Theme not found: <name>` for a name it cannot resolve. A predicate returns
	// false instead of throwing.
	if IsLightTheme("no-such-theme") {
		t.Fatal("an unknown theme must not report a light appearance")
	}
}

// Upstream (pi v1.5.2 modes/interactive/interactive-mode.ts
// getMarkdownThemeWithSettings) applies markdown.codeBlockIndent at every render
// site, so the setting reaches the transcript from the first frame and again
// after /reload.
func TestMarkdownThemeAppliesCodeBlockIndent(t *testing.T) {
	indent := "    "
	app, cleanup := newTestAppConfigured(t, false, func(settings *coding.SettingsManager, _ *AppOptions) {
		settings.ApplyOverrides(&coding.Settings{Markdown: &coding.SettingsMarkdown{CodeBlockIndent: &indent}})
	})
	defer cleanup()
	if app.transcript.MarkdownTheme == nil || app.transcript.MarkdownTheme.CodeBlockIndent != indent {
		t.Fatalf("transcript code block indent = %v, want %q", app.transcript.MarkdownTheme, indent)
	}
	if app.events.MarkdownTheme == nil || app.events.MarkdownTheme.CodeBlockIndent != indent {
		t.Fatalf("events code block indent = %v, want %q", app.events.MarkdownTheme, indent)
	}

	// /reload re-reads the setting, as the per-render read does.
	changed := "\t"
	app.settings.ApplyOverrides(&coding.Settings{Markdown: &coding.SettingsMarkdown{CodeBlockIndent: &changed}})
	app.Init(context.Background())
	app.applySettingsDependentUI()
	if got := app.transcript.MarkdownTheme.CodeBlockIndent; got != changed {
		t.Fatalf("code block indent after reload = %q, want %q", got, changed)
	}
	if got := app.events.MarkdownTheme.CodeBlockIndent; got != changed {
		t.Fatalf("events code block indent after reload = %q, want %q", got, changed)
	}
}
